# A standard-library tabbed text editor with explicit UTF-8 saves.
import tkinter as tk
from tkinter.scrolledtext import ScrolledText
from pathlib import Path
import os
import tempfile


def tabs_current(app):
    return app.notes.get(str(app.NotesTabs.select()))


def tabs_title(app, tab):
    # Compare against saved content rather than clearing the dirty state on focus.
    note = app.notes.get(str(tab))
    if note is None:
        return
    dirty = note["text"].get("1.0", "end-1c") != note["saved"]
    app.NotesTabs.tab(tab, text=note["title"] + (" *" if dirty else ""))


def tabs_modified(app, tab):
    note = app.notes.get(str(tab))
    if note is not None and note["text"].edit_modified():
        note["text"].edit_modified(False)
        tabs_title(app, tab)


def tabs_add(app):
    # New pages are built dynamically; the first page is editable in the designer.
    if len(app.notes) >= 20:
        messagebox.showerror("New note", "At most 20 notes can be open.")
        return None
    app.note_counter += 1
    title = "Note " + str(app.note_counter)
    frame = app.NotesTabs.add_page(title)
    text = ScrolledText(frame, undo=True, wrap="word", font=("Helvetica", 13))
    text.pack(fill="both", expand=True)
    tab = str(frame)
    app.notes[tab] = {"text": text, "path": None, "title": title, "saved": ""}
    text.edit_modified(False)
    text.bind("<<Modified>>", lambda event: tabs_modified(app, tab))
    app.NotesTabs.select(frame)
    text.focus_set()
    return tab


def tabs_save(app, note=None):
    # A temporary file prevents partial writes from truncating an existing note.
    note = note if note is not None else tabs_current(app)
    if note is None:
        return False
    filename = note["path"] or filedialog.asksaveasfilename(parent=app.Form1, defaultextension=".txt", filetypes=[("Text files", "*.txt")])
    if not filename:
        return False
    temporary = None
    try:
        path = Path(filename)
        content = note["text"].get("1.0", "end-1c")
        descriptor, temporary = tempfile.mkstemp(dir=path.parent, prefix=".note-", suffix=".tmp")
        with os.fdopen(descriptor, "w", encoding="utf-8") as stream:
            stream.write(content)
            stream.flush()
            os.fsync(stream.fileno())
        os.replace(temporary, path)
        note.update(path=str(path), saved=content, title=path.name)
        for tab, item in app.notes.items():
            if item is note:
                tabs_title(app, tab)
        app.StatusLabel.configure(text="Saved: " + str(path))
        return True
    except (OSError, UnicodeError) as error:
        messagebox.showerror("Save note", str(error), parent=app.Form1)
        return False
    finally:
        if temporary is not None:
            Path(temporary).unlink(missing_ok=True)


def tabs_confirm(app, note):
    if note["text"].get("1.0", "end-1c") == note["saved"]:
        return True
    answer = messagebox.askyesnocancel("Unsaved note", "Save changes to " + note["title"] + "?", parent=app.Form1)
    return False if answer is None else tabs_save(app, note) if answer else True


def tabs_close(app):
    tab = str(app.NotesTabs.select())
    note = app.notes.get(tab)
    if note is None or not tabs_confirm(app, note):
        return
    app.NotesTabs.forget(tab)
    del app.notes[tab]
    for title, frame in list(app.NotesTabs.pages.items()):
        if str(frame) == tab:
            frame.destroy()
            del app.NotesTabs.pages[title]
            break
    if not app.notes:
        tabs_add(app)


def tabs_open(app):
    filename = filedialog.askopenfilename(parent=app.Form1, filetypes=[("Text files", "*.txt"), ("All files", "*")])
    if not filename:
        return
    try:
        path = Path(filename).resolve()
        if path.stat().st_size > 2 * 1024 * 1024:
            raise ValueError("Files are limited to 2 MiB.")
        content = path.read_text(encoding="utf-8-sig")
        if "\x00" in content:
            raise ValueError("Binary files are not supported.")
    except (OSError, ValueError, UnicodeError) as error:
        messagebox.showerror("Open note", str(error), parent=app.Form1)
        return
    for tab, note in app.notes.items():
        if note["path"] and Path(note["path"]).resolve() == path:
            app.NotesTabs.select(tab)
            note["text"].focus_set()
            return
    tab = tabs_add(app)
    if tab is None:
        return
    note = app.notes[tab]
    note["text"].insert("1.0", content)
    note["text"].edit_modified(False)
    note.update(path=str(path), saved=content, title=path.name)
    tabs_title(app, tab)


def tabs_close_app(app):
    # Cancellation leaves all tabs open, even if earlier notes were saved.
    for note in list(app.notes.values()):
        if not tabs_confirm(app, note):
            return
    app.root.destroy()
